#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-21

# Integration test: publish-skills.mjs (Skills API publish rail, #3628).
#
# Hermetic — every case runs against a synthetic PUBLISH_SKILLS_DIR fixture
# under $WORK_DIR, never the real plugins/ork/skills tree, and NEVER passes
# --publish with a real ANTHROPIC_API_KEY. No network call happens anywhere
# in this file. Mirrors tests/integration/test-platform-watch.sh style.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"

RED='\033[0;31m'
GREEN='\033[0;32m'
NC='\033[0m'

PASS=0
FAIL=0
log_pass() { echo -e "  ${GREEN}✓${NC} $1"; PASS=$((PASS + 1)); }
log_fail() { echo -e "  ${RED}✗${NC} $1 — $2"; FAIL=$((FAIL + 1)); }

echo "Publish Skills Tests (#3628)"
echo "============================="

cd "$PROJECT_ROOT"

WORK_DIR=$(mktemp -d "${TMPDIR:-/tmp}/ork.XXXXXX")
trap 'rm -rf "$WORK_DIR"' EXIT

SCRIPT="scripts/publish-skills.mjs"

# ============================================================================
# Fixture helpers
# ============================================================================

# make_skill <fixture_dir> <dir_name> <name> <description>
# Writes a minimal valid-shaped SKILL.md (plus one bundled reference file) so
# every fixture skill also exercises file-bundling, not just frontmatter.
make_skill() {
  local fixture_dir="$1" dir_name="$2" name="$3" desc="$4"
  mkdir -p "$fixture_dir/$dir_name/references"
  cat > "$fixture_dir/$dir_name/SKILL.md" <<EOF
---
name: $name
description: "$desc"
tags: [test]
version: 1.0.0
author: Test
user-invocable: false
complexity: low
---

# $name

Body content.
EOF
  echo "reference content" > "$fixture_dir/$dir_name/references/notes.md"
}

run_publish() {
  # Runs the script with the given fixture dir + extra args; sets EXIT, writes stdout+stderr to $1.
  local out="$1" fixture_dir="$2"; shift 2
  EXIT=0
  PUBLISH_SKILLS_DIR="$fixture_dir" node "$SCRIPT" "$@" > "$out" 2>&1 || EXIT=$?
}

# ============================================================================
# Test 1: happy path — two valid skills, exit 0, both PASS, dry-run payload printed
# ============================================================================
HAPPY_DIR="$WORK_DIR/happy"
mkdir -p "$HAPPY_DIR"
make_skill "$HAPPY_DIR" alpha-skill alpha-skill "Does alpha things. Use when the user asks for alpha work."
make_skill "$HAPPY_DIR" beta-skill beta-skill "Does beta things. Use when the user asks for beta work."

run_publish "$WORK_DIR/run1.txt" "$HAPPY_DIR"
if [ "$EXIT" = "0" ]; then
  log_pass "Happy path: exit 0"
else
  log_fail "Happy path exit" "expected 0, got $EXIT (output: $(cat "$WORK_DIR/run1.txt"))"
fi

if grep -qF 'PASS  alpha-skill' "$WORK_DIR/run1.txt" && grep -qF 'PASS  beta-skill' "$WORK_DIR/run1.txt"; then
  log_pass "Both fixture skills reported PASS"
else
  log_fail "PASS reporting" "expected PASS lines for both skills"
fi

if grep -qF 'Summary: 2 passed, 0 failed, 2 total' "$WORK_DIR/run1.txt"; then
  log_pass "Summary line correct (2 passed, 0 failed)"
else
  log_fail "Summary line" "expected '2 passed, 0 failed, 2 total'"
fi

if grep -qF '"mode": "dry-run"' "$WORK_DIR/run1.txt" && grep -qF 'references/notes.md' "$WORK_DIR/run1.txt"; then
  log_pass "Dry-run payload composed and includes bundled file"
else
  log_fail "Dry-run payload" "expected mode:dry-run JSON listing references/notes.md"
fi

if grep -qF 'Mode: DRY RUN (no network calls)' "$WORK_DIR/run1.txt"; then
  log_pass "Dry-run mode banner printed"
else
  log_fail "Dry-run banner" "expected the no-network-calls banner"
fi

# ============================================================================
# Test 2: name constraint violation — invalid chars, exit 1, never skipped
# ============================================================================
NAME_DIR="$WORK_DIR/name-violation"
mkdir -p "$NAME_DIR"
make_skill "$NAME_DIR" bad-name-dir "Bad_Name" "Does things. Use when needed."
make_skill "$NAME_DIR" ok-skill ok-skill "Does ok things. Use when the user asks."

run_publish "$WORK_DIR/run2.txt" "$NAME_DIR"
if [ "$EXIT" = "1" ]; then
  log_pass "Name violation: exit 1"
else
  log_fail "Name violation exit" "expected 1, got $EXIT"
fi

if grep -qF 'FAIL  bad-name-dir' "$WORK_DIR/run2.txt" && grep -qF '[name-invalid-chars]' "$WORK_DIR/run2.txt"; then
  log_pass "Invalid name reported with exact rule + file path"
else
  log_fail "Name violation report" "expected FAIL bad-name-dir with [name-invalid-chars]"
fi

if grep -qF 'PASS  ok-skill' "$WORK_DIR/run2.txt"; then
  log_pass "Valid sibling skill still reported (never silently skipped)"
else
  log_fail "Sibling skill" "expected ok-skill still reported as PASS"
fi

# ============================================================================
# Test 3: name too long (> 64 chars) — exit 1, exact rule
# ============================================================================
LONGNAME_DIR="$WORK_DIR/long-name"
mkdir -p "$LONGNAME_DIR"
LONG_NAME=$(printf 'a%.0s' $(seq 1 65))
make_skill "$LONGNAME_DIR" long-name-skill "$LONG_NAME" "Does things. Use when needed."

run_publish "$WORK_DIR/run3.txt" "$LONGNAME_DIR"
if [ "$EXIT" = "1" ] && grep -qF '[name-too-long]' "$WORK_DIR/run3.txt"; then
  log_pass "Name too long: exit 1 with [name-too-long]"
else
  log_fail "Name length violation" "expected exit 1 + [name-too-long], got exit $EXIT"
fi

# ============================================================================
# Test 4: description too long (> 1024 chars) — exit 1, exact rule
# ============================================================================
LONGDESC_DIR="$WORK_DIR/long-desc"
mkdir -p "$LONGDESC_DIR"
LONG_DESC="Use when needed. $(printf 'x%.0s' $(seq 1 1100))"
make_skill "$LONGDESC_DIR" long-desc-skill long-desc-skill "$LONG_DESC"

run_publish "$WORK_DIR/run4.txt" "$LONGDESC_DIR"
if [ "$EXIT" = "1" ] && grep -qF '[description-too-long]' "$WORK_DIR/run4.txt"; then
  log_pass "Description too long: exit 1 with [description-too-long]"
else
  log_fail "Description length violation" "expected exit 1 + [description-too-long], got exit $EXIT"
fi

# ============================================================================
# Test 5: description missing "when" — exit 1, exact rule
# ============================================================================
NOWHEN_DIR="$WORK_DIR/no-when"
mkdir -p "$NOWHEN_DIR"
make_skill "$NOWHEN_DIR" no-when-skill no-when-skill "Does things for the user, no trigger stated."

run_publish "$WORK_DIR/run5.txt" "$NOWHEN_DIR"
if [ "$EXIT" = "1" ] && grep -qF '[description-missing-when]' "$WORK_DIR/run5.txt"; then
  log_pass "Description missing 'when': exit 1 with [description-missing-when]"
else
  log_fail "Missing-when violation" "expected exit 1 + [description-missing-when], got exit $EXIT"
fi

# ============================================================================
# Test 5b: usage guidance without the literal word "when" must PASS.
# The first cut of the rule matched /\bwhen\b/ and failed two real catalog
# skills that state their trigger as "Use for ..." (glyph) and "Use after ..."
# (release-sync). Fail-closed plus a literal token match is a false positive
# that blocks correct skills forever, so these phrasings are asserted here.
# ============================================================================
WHENALT_DIR="$WORK_DIR/when-alt"
mkdir -p "$WHENALT_DIR"
make_skill "$WHENALT_DIR" use-for-skill use-for-skill \
  "Render an answer as ASCII art plus semantic emojis inline. Use for a fast visual take on status, comparisons, or trade-offs."
make_skill "$WHENALT_DIR" use-after-skill use-after-skill \
  "Syncs release content to the knowledge base. Use after tagging a new version to propagate release knowledge."

run_publish "$WORK_DIR/run5b.txt" "$WHENALT_DIR"
if [ "$EXIT" = "0" ] && ! grep -qF '[description-missing-when]' "$WORK_DIR/run5b.txt"; then
  log_pass "Usage guidance without the word 'when' passes (Use for / Use after)"
else
  log_fail "when-alt phrasing" "expected exit 0 and no missing-when violation, got exit $EXIT"
fi

# ============================================================================
# Test 6: empty enumeration guard — could-not-observe, never "nothing to publish"
# ============================================================================
EMPTY_DIR="$WORK_DIR/empty"
mkdir -p "$EMPTY_DIR"

run_publish "$WORK_DIR/run6.txt" "$EMPTY_DIR"
if [ "$EXIT" = "1" ] && grep -qF 'could-not-observe' "$WORK_DIR/run6.txt"; then
  log_pass "Empty enumeration: exit 1 with could-not-observe"
else
  log_fail "Empty enumeration guard" "expected exit 1 + 'could-not-observe', got exit $EXIT: $(cat "$WORK_DIR/run6.txt")"
fi

# The script's own message explicitly disclaims the "nothing to publish"
# reading (that's the point — an honest could-not-observe beats a confidently
# wrong success), so assert on the disclaiming shape rather than absence of
# the substring, which the disclaimer itself necessarily contains.
if grep -qF 'could-not-observe, never "nothing to publish"' "$WORK_DIR/run6.txt"; then
  log_pass "Empty enumeration explicitly disclaims a nothing-to-publish reading"
else
  log_fail "Empty enumeration phrasing" "expected the explicit could-not-observe disclaimer"
fi

# ============================================================================
# Test 7: --skill selects exactly one skill, dry-run limited to it
# ============================================================================
SELECT_DIR="$WORK_DIR/select"
mkdir -p "$SELECT_DIR"
make_skill "$SELECT_DIR" alpha-skill alpha-skill "Does alpha things. Use when the user asks for alpha work."
make_skill "$SELECT_DIR" beta-skill beta-skill "Does beta things. Use when the user asks for beta work."
make_skill "$SELECT_DIR" gamma-skill gamma-skill "Does gamma things. Use when the user asks for gamma work."

run_publish "$WORK_DIR/run7.txt" "$SELECT_DIR" --skill beta-skill
if [ "$EXIT" = "0" ] && grep -qF 'Summary: 1 passed, 0 failed, 1 total' "$WORK_DIR/run7.txt"; then
  log_pass "--skill limits the run to exactly one skill"
else
  log_fail "--skill selection" "expected exit 0 + summary of 1 total, got exit $EXIT"
fi

if grep -qF 'PASS  beta-skill' "$WORK_DIR/run7.txt" && ! grep -qF 'alpha-skill' "$WORK_DIR/run7.txt" && ! grep -qF 'gamma-skill' "$WORK_DIR/run7.txt"; then
  log_pass "--skill excludes the other fixture skills from output"
else
  log_fail "--skill exclusivity" "expected only beta-skill in output"
fi

# ============================================================================
# Test 8: --skill with an unknown name refuses cleanly, exit 1
# ============================================================================
run_publish "$WORK_DIR/run8.txt" "$SELECT_DIR" --skill does-not-exist
if [ "$EXIT" = "1" ] && grep -qF 'not found' "$WORK_DIR/run8.txt"; then
  log_pass "--skill unknown name: exit 1 with 'not found'"
else
  log_fail "--skill unknown name" "expected exit 1 + 'not found', got exit $EXIT"
fi

# ============================================================================
# Test 9: --limit caps the processed set (alphabetical)
# ============================================================================
run_publish "$WORK_DIR/run9.txt" "$SELECT_DIR" --limit 2
if [ "$EXIT" = "0" ] && grep -qF 'Summary: 2 passed, 0 failed, 2 total' "$WORK_DIR/run9.txt"; then
  log_pass "--limit 2 caps the run to 2 of 3 fixture skills"
else
  log_fail "--limit" "expected exit 0 + summary of 2 total, got exit $EXIT"
fi

if grep -qF 'PASS  alpha-skill' "$WORK_DIR/run9.txt" && grep -qF 'PASS  beta-skill' "$WORK_DIR/run9.txt" && ! grep -qF 'gamma-skill' "$WORK_DIR/run9.txt"; then
  log_pass "--limit 2 keeps the first two alphabetically, drops the third"
else
  log_fail "--limit ordering" "expected alpha+beta present, gamma absent"
fi

# ============================================================================
# Test 10: --publish without ANTHROPIC_API_KEY refuses cleanly, exit 1, no network
# ============================================================================
EXIT=0
PUBLISH_SKILLS_DIR="$HAPPY_DIR" env -u ANTHROPIC_API_KEY node "$SCRIPT" --publish > "$WORK_DIR/run10.txt" 2>&1 || EXIT=$?
if [ "$EXIT" = "1" ] && grep -qF 'ANTHROPIC_API_KEY' "$WORK_DIR/run10.txt"; then
  log_pass "--publish without ANTHROPIC_API_KEY: exit 1, names the missing key"
else
  log_fail "--publish without key" "expected exit 1 + ANTHROPIC_API_KEY mention, got exit $EXIT: $(cat "$WORK_DIR/run10.txt")"
fi

if ! grep -qiF 'publishing' "$WORK_DIR/run10.txt"; then
  log_pass "--publish without key never attempts an upload"
else
  log_fail "--publish without key" "must refuse before attempting any upload"
fi

echo ""
echo "Results: $PASS passed, $FAIL failed"
[ "$FAIL" = "0" ] || exit 1
exit 0
